def signal(obs):
    # C momentum: past 50 days
    # use hist over 60
    try:
        m = obs.hist('C','mid',60)
        if m[0]!=m[0] or m[-1]!=m[-1]:
            return {}
        past50 = m[-1] - m[0] if len(m)>=51 else m[-1]-m[10]
        # alternative: past10 also
        # target proportional to past50 clipped
        # scale: 1 corresponds to ~10c move (std ~? C vol per step 0.98 => 50 steps std ~7c). So clip at 10c
        v = past50/12.0
        if v>1: v=1
        if v<-1: v=-1
        # deadzone small
        if abs(v)<0.1:
            v=0
        return {'C': float(v)}
    except:
        return {}

def signal(obs):
    try:
        h = obs.hist('C', 'mid', 61)
        if h is None:
            return {}
        # h is array length 61, oldest first
        # need to handle NaNs: find last valid and one 50 steps prior
        # if any NaN, fallback to 0
        if len(h) < 51:
            return {}
        # quick nan check
        # use last element and element 50 steps before last (index -51)
        a = h[-1]
        b = h[-51]
        # also check intermediate? if either nan, try to find nearest valid
        if a != a or b != b:  # nan
            # search backwards for valid a
            # find last valid in last 5
            for k in range(1, 6):
                if len(h)-k >= 0 and h[-k] == h[-k]:
                    a = h[-k]
                    break
            for k in range(51, 56):
                idx = len(h)-k
                if idx >=0 and h[idx] == h[idx]:
                    b = h[idx]
                    break
            if a != a or b != b:
                return {'C': 0.0}
        past = a - b  # approx 50-step past return in cents
        # normalize: std of 50-step ~7c, clip at ~12c
        v = past / 12.0
        if v > 1.0:
            v = 1.0
        if v < -1.0:
            v = -1.0
        if abs(v) < 0.10:
            v = 0.0
        # also require some liquidity: check spread not too wide vs average
        # if spread > 15c, reduce size
        s = obs.last('C', 'spread')
        if s == s and s > 15:
            v = v * 0.5
        return {'C': float(v)}
    except:
        return {}

def signal(obs):
    try:
        h = obs.hist('C', 'mid', 61)
        if h is None or len(h) < 61:
            return {}
        a = h[-1]
        b = h[-51]
        if a != a or b != b:
            return {'C': 0.0}
        past = a - b
        # only trade when past is substantial (|past| > 6c ~ 0.75 std)
        # threshold tuned to reduce turnover and ensure edge > spread
        if abs(past) < 6.0:
            return {'C': 0.0}
        # scale diminishing beyond 12c
        v = past / 14.0
        if v > 1.0: v = 1.0
        if v < -1.0: v = -1.0
        # also check recent spread to avoid high-cost regimes
        # if spread too wide, stay flat
        s = obs.last('C', 'spread')
        if s == s and s > 12:
            return {'C': 0.0}
        return {'C': float(v)}
    except:
        return {}

