# autocorr of diff at lags 1,5,10,30,50
def autocorr(x, lag):
    m=0.0; c=0
    for v in x:
        if v==v: m+=v; c+=1
    m=m/c
    num=0.0; den=0.0
    c2=0
    for i in range(len(x)-lag):
        if x[i]==x[i] and x[i+lag]==x[i+lag]:
            num+=(x[i]-m)*(x[i+lag]-m)
            c2+=1
    for i in range(len(x)):
        if x[i]==x[i]: den+=(x[i]-m)*(x[i]-m)
    return num/den if den!=0 else 0
