        for i in range(n-h):
            d=diff[i]
            if d==d and abs(d)>T:
                dn=diff[i+h]
                if dn==dn:
                    # convergence = (abs(d)-abs(dn)) positive means reverted
                    s+=(abs(d)-abs(dn))
                    c+=1
        res['T%d_h%d'%(T,h)]=dict(avg_revert=s/c if c>0 else 0, n=c)
