def signal(obs):
    # IDX 50-step mean reversion only
    m = obs.hist('IDX','mid',60)
    if m is None or len(m)<60:
        return {}
    # nan handling
    cur = m[-1]
    past = m[-51] if len(m)>=51 else m[0]
    if not (cur==cur and past==past):
        return {}
    pr = cur - past
    # normalize? threshold 5
    # target opposite of past return, scaled
    t = -pr/10.0
    if t>1: t=1
    if t<-1: t=-1
    # deadzone small
    if abs(t)<0.1:
        t=0
    return {'IDX': float(t)}

