    # C momentum 50-step
    m = obs.hist('C','mid',60)
    if m is None or len(m)<60:
        return {}
    cur = m[-1]; past = m[-51]
    if not (cur==cur and past==past):
        return {}
    pr = cur - past
    t = pr/15.0
    if t>1: t=1
    if t<-1: t=-1
    if abs(t)<0.15:
        t=0
    return {'C': float(t)}

def signal(obs):
    a = obs.hist('A','mid',5)
    ax = obs.hist('A.X','mid',5)
    if a is None or ax is None or len(a)<5:
        return {}
    c0 = a[-1]; x0 = ax[-1]
    if not (c0==c0 and x0==x0):
        return {}
    d = c0 - x0
    T = 13.0
    if d > T:
        # A rich vs AX: sell A buy AX
        return {'A': -1.0, 'A.X': 1.0}
    elif d < -T:
        return {'A': 1.0, 'A.X': -1.0}
    elif abs(d) < 3.0:
        return {'A': 0.0, 'A.X': 0.0}
    else:
        return {}

