    # hedged premium reversion with adaptive rolling window
    # long basket (A,B,C weighted) short IDX when premium high
    a = obs.last('A','mid')
    b = obs.last('B','mid')
    c = obs.last('C','mid')
    idx = obs.last('IDX','mid')
    if a is None or b is None or c is None or idx is None:
        return {}
    # nan check
    if a!=a or b!=b or c!=c or idx!=idx:
        return {}
    basket = 0.3333*a + 0.6667*b + 0.1667*c
    prem = idx - basket
