    if 'pos' not in s:
        s['pos'] = 0.0
    pos = s['pos']
    # try adaptive rolling window 300
    w = 300
    try:
        ha = obs.hist('A','mid',w)
        hb = obs.hist('B','mid',w)
        hc = obs.hist('C','mid',w)
        hi = obs.hist('IDX','mid',w)
        # check lengths
        if ha is None or hb is None or hc is None or hi is None:
            raise Exception("no hist")
        # convert to arrays (already numpy)
        # filter nan: if too many nans skip adaptive
        # compute basket hist
        # ensure same length
        n = len(ha)
        if n < 100:
            raise Exception("short hist")
        # compute prem hist where all finite
        # use numpy operations
        # ha etc may contain nan
        basket_hist = 0.3333*ha + 0.6667*hb + 0.1667*hc
        prem_hist = hi - basket_hist
        # remove nan
        mask = np.isfinite(prem_hist)
        cnt = int(np.sum(mask))
        if cnt < 200:
            raise Exception("not enough")
        ph = prem_hist[mask]
        mean = float(np.mean(ph))
        std = float(np.std(ph))
        if std < 5.0:
            std = 5.0
        if std != std or mean != mean:
            raise Exception("nan stats")
        z = (prem - mean) / std
        # thresholds
        entry = 1.3
        exit_thr = 0.3
        if pos == 0:
            if z > entry:
                pos = 1.0   # long basket short idx
            elif z < -entry:
                pos = -1.0  # short basket long idx
        elif pos > 0:
            if z < exit_thr:
                pos = 0.0
                if z < -entry:
                    pos = -1.0
        elif pos < 0:
