def signal(obs):
    # lead-lag: IDX leads basket. Buy basket when IDX has risen, sell when fallen.
    # low turnover, no hedge to save spread, adapt threshold to vol
    Lb = 50
    try:
        hi = obs.hist('IDX','mid', Lb+5)
        if hi is None or len(hi) < Lb+5:
            return {}
        # compute IDX return over Lb
        # need last Lb return: hi[-1] - hi[-1-Lb]
        # hist gives last n, with hi[-1] = latest mid (approx)
        # ensure finite
        if not np.isfinite(hi[-1]) or not np.isfinite(hi[0]):
            return {}
        # use Lb lookback from end
        idx_now = float(hi[-1])
        idx_past = float(hi[-1 - Lb]) if len(hi) > Lb else float(hi[0])
        if not np.isfinite(idx_past):
            return {}
        ret = idx_now - idx_past
        # estimate vol for threshold adaptation: std of 50-step returns in window
        # compute rolling std using hist of IDX
        # use longer window 300 to estimate vol
        hw = obs.hist('IDX','mid', 300)
        if hw is not None and len(hw) >= 100:
            # compute 50-step diffs in window
            diffs = hw[50:] - hw[:-50]
            diffs = diffs[np.isfinite(diffs)]
            if len(diffs) > 50:
                vol = float(np.std(diffs))
                if not np.isfinite(vol) or vol < 8:
                    vol = 12.0
            else:
                vol = 12.0
        else:
            vol = 12.0
        thr = 0.6 * vol  # about 7-15 cents
        # hysteresis to reduce turnover
        s = obs.state
        if 'pos' not in s:
            s['pos'] = 0.0
        pos = s['pos']
        # smooth signal: only change if ret exceeds thr
        if pos == 0:
            if ret > thr:
                pos = 1.0
            elif ret < -thr:
                pos = -1.0
        elif pos > 0:
            if ret < -thr*0.5:  # need opposite signal to flip
                pos = -1.0
            elif ret < 0 and abs(ret) < 2:
                # optional exit to zero if momentum fades small? keep to reduce churn
                # we exit only when ret crosses zero significantly negative
                pass
            # also exit to 0 if ret near zero for long time? keep position until opposite
        elif pos < 0:
            if ret > thr*0.5:
                pos = 1.0
        # alternative: allow flat when ret small magnitude
        # if abs(ret) < thr*0.3, go flat to reduce holding through noise
        # but that increases turnover, so keep momentum hold
        # implement flat exit if ret crosses zero weakly? Add timeout?
        # only go flat if strongly mean revert? For now keep binary.

        # To ensure low turnover, don't go to 0, just flip -1/1
        # but backtest expects -1,0,1? We allow 0 only at start
        s['pos'] = pos
        if pos == 0:
            return {'A':0.0,'B':0.0,'C':0.0}
        # scale basket weights to be comparable to IDX: use same weighting as basket definition
        # we trade basket only, hedged not needed to save spread/fees
        # weight each component equally to basket: 0.33,0.67,0.17 but normalize to max 1 exposure
        # Use proportional exposure: A 0.5, B 1.0, C 0.25 scaled by pos
        # simplify: use basket weights * pos * scale factor 1.5 to get approx 15 lots total weighted
        # engine max 15 lots per asset, so pos=1 gives A 0.5 ~7.5 lots, B 1.0 15 lots, C 0.25 3.75 lots
        scal = 1.0
        return {'A': float(pos*0.5*scal), 'B': float(pos*1.0*scal), 'C': float(pos*0.25*scal), 'IDX': 0.0, 'A.X':0.0,'B.X':0.0,'C.X':0.0}
    except Exception:
        return {}

