def corr(x,y):
    m=np.isfinite(x)&np.isfinite(y)
    x=x[m]; y=y[m]
    if len(x)<300:
        return float('nan')
    xm=x.mean(); ym=y.mean()
    denom=np.sqrt(((x-xm)**2).sum()*((y-ym)**2).sum())
    if denom==0:
        return float('nan')
    return float(((x-xm)*(y-ym)).sum()/denom)

