    m = H[a]['mid']
    n = len(m)
    # past 50 vs forward 50 correlation, split halves
    def corr(past, fwd):
        # filter nan
        s = 0.0; sp=0.0; sf=0.0; sp2=0.0; sf2=0.0; cnt=0
        for i in range(len(past)):
            x = past[i]; y = fwd[i]
            if x==x and y==y:
                s+=1
                sp+=x; sf+=y; sp2+=x*x; sf2+=y*y
        # need cross term; redo loop for cov
        # compute means
        if s<10:
            return 0.0
        mx=sp/s; my=sf/s
        vx=sp2/s-mx*mx; vy=sf2/s-my*my
        if vx<=0 or vy<=0:
            return 0.0
        cov=0.0; c=0
        for i in range(len(past)):
            x=past[i]; y=fwd[i]
            if x==x and y==y:
                cov+=(x-mx)*(y-my); c+=1
        cov=cov/c
        return cov/((vx**0.5)*(vy**0.5))
    for L in [10,30,50,100]:
        past=[]
        fwd=[]
        for i in range(L, n-L):
            if m[i]==m[i] and m[i-L]==m[i-L] and m[i+L]==m[i+L]:
                past.append(m[i]-m[i-L])
                fwd.append(m[i+L]-m[i])
        # subsample every 10 to reduce compute
        past2=past[::10]; fwd2=fwd[::10]
        # halves
        h=len(past2)//2
        c_all=corr(past2,fwd2)
        c1=corr(past2[:h],fwd2[:h])
        c2=corr(past2[h:],fwd2[h:])
        result[a+'_L'+str(L)]=[round(c_all,4),round(c1,4),round(c2,4)]

