def seg_ic(sym, lag=50, fwd=50):
    px = H[sym]['mid']
    px2 = H[sym+'.X']['mid'] if sym!='IDX' else px
    n=len(px)
    out={}
    for name,a,b in [('early',0,5000),('mid',5000,10000),('late',10000,15000),('recent',12500,15750)]:
      s1=px[a:b]; s2=px2[a:b]
      r=((s1[lag:]-s1[:-lag])+(s2[lag:]-s2[:-lag]))/2.0
      r0=r[:-fwd]; f1=s1[lag+fwd:]-s1[lag:-fwd]
      m=np.isfinite(r0)&np.isfinite(f1)
      r0=r0[m]; f1=f1[m]
      ic=float(np.corrcoef(r0,f1)[0,1]) if len(r0)>200 else float('nan')
      out[name]={'ic':ic,'mean_fwd_abs':float(np.mean(np.abs(f1)))}
    return out
