                    tgt = -1.0
            else:
                if tgt > 0.0 and mom < 0.0:
                    tgt = -1.0 if mom < -10.0 else 0.0
                elif tgt < 0.0 and mom > 0.0:
                    tgt = 1.0 if mom > 10.0 else 0.0
            if tgt != pc:
                out['C'] = float(tgt)
                st['pc'] = float(tgt)
